/* UI state, deterministic visualization and bilingual content binding. */
'use strict';
const P=PSI,$=id=>document.getElementById(id),reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const defaultStates=[{velocity:-12},{threshold:.25},{noise:.25},{error:8,reject:false},{length:.25},{season:5,modelType:'linear'}];
const stochasticStages=[1,2,4,5],sampleSeeds=Array.from({length:6},()=>P.randomSeed()),heroSeed=P.randomSeed();
let states=defaultStates.map(x=>({...x})),stage=0,data,progress=1,playing=false,lastTime=0,heroVisible=true,labVisible=true,playbackSpeed=1,lastMetricTime=0;
let lang='zh';try{lang=new URLSearchParams(location.search).get('lang')||localStorage.getItem('psi-language')||'zh';}catch{}if(!['zh','en'].includes(lang))lang='zh';
const U=()=>NOTEBOOK_CONTENT[lang].ui,C=()=>NOTEBOOK_CONTENT[lang].chapters[stage],T=(zh,en)=>lang==='zh'?zh:en;
const tags=['OBSERVE','SELECT','ESTIMATE','CONNECT','PREDICT','VALIDATE'];
const legends={zh:[[['line','连续相位'],['dot','缠绕观测']],[['dot','保留候选点'],['dash','其他像元 / 高离散度序列']],[['line','深色 = 高 γ'],['dot','当前最优候选']],[['line','正常弧'],['dash','已知含偏差弧']],[['line','共用灰度：−2.2 至 +1.6 rad'],['dot','大气残差采样点']],[['dot','位移观测'],['line','拟合值'],['dash','合成真值']]],en:[[['line','Continuous phase'],['dot','Wrapped observations']],[['dot','Retained candidates'],['dash','Other pixels / high-dispersion series']],[['line','Darker = higher γ'],['dot','Running optimum']],[['line','Valid arcs'],['dash','Known biased arc']],[['line','Shared scale: −2.2 to +1.6 rad'],['dot','Atmospheric samples']],[['dot','Observations'],['line','Fitted model'],['dash','Synthetic truth']]]};
const descriptions={zh:['线性视线向位移对应的连续相位与缠绕观测。两图采用同步时间游标。','根据 28 期振幅计算 180 个像元的离散度，分析门限与候选保留率。','按候选顺序搜索速度与残余高程。热图与相量图显示当前搜索结果。','固定参考点，利用弧速度差估计点速度，并比较已知异常弧的影响。','以独立的大气残差样本预测空间相位屏，比较改正前后的网格误差。','对相同位移序列拟合线性或年周期模型，比较速度估计与残差结构。'],en:['Continuous and wrapped phase for linear LOS displacement, with synchronized time cursors.','Amplitude dispersion from 28 acquisitions for 180 pixels; examine threshold-dependent retention.','Search velocity and residual height in candidate order. The heatmap and phasors show the running result.','Fix a reference point and recover point velocities from arc differences, with a known biased arc.','Predict a spatial phase screen from isolated atmospheric samples and compare correction errors.','Fit linear or annual models to the same displacement series and compare velocity and residuals.']};
const plotNames=['CONTINUOUS / WRAPPED PHASE','CANDIDATE MAP / AMPLITUDE SERIES','AMBIGUITY FUNCTION / RESIDUAL PHASORS','RELATIVE VELOCITY / NETWORK ADJUSTMENT','ATMOSPHERIC PHASE / SPATIAL PREDICTION','DISPLACEMENT FIT / RESIDUAL STRUCTURE'];
function rangeControl(key,label,min,max,step,value,unit=''){return `<div class="control"><label for="control-${key}">${label}<output id="value-${key}">${value} ${unit}</output></label><input id="control-${key}" data-key="${key}" data-unit="${unit}" type="range" min="${min}" max="${max}" step="${step}" value="${value}"></div>`;}
function buildControls(){const s=states[stage],c=U().controls;let html='';if(stage===0)html=rangeControl('velocity',c[0],-25,25,1,s.velocity,'mm/yr');if(stage===1)html=rangeControl('threshold',c[1],.05,.65,.01,s.threshold);if(stage===2)html=rangeControl('noise',c[2],0,1.5,.05,s.noise,'rad');if(stage===3)html=rangeControl('error',c[3],0,16,.5,s.error,'mm/yr')+`<label class="check"><input type="checkbox" data-key="reject" ${s.reject?'checked':''}>${c[4]}</label>`;if(stage===4)html=rangeControl('length',c[5],.05,.65,.02,s.length);if(stage===5)html=rangeControl('season',c[6],0,10,.5,s.season,'mm')+`<div class="control"><label for="modelType">${c[7]}</label><select id="modelType" data-key="modelType"><option value="linear" ${s.modelType==='linear'?'selected':''}>${c[8]}</option><option value="seasonal" ${s.modelType==='seasonal'?'selected':''}>${c[9]}</option></select></div>`;$('controls').innerHTML=html;
$('controls').querySelectorAll('input,select').forEach(el=>el.addEventListener('input',()=>{states[stage][el.dataset.key]=el.type==='checkbox'?el.checked:el.tagName==='SELECT'?el.value:Number(el.value);if(el.type==='range')$('value-'+el.dataset.key).textContent=el.value+' '+el.dataset.unit;progress=1;pause();recompute();drawLab();updateProgress();}));}
function metric(label,value,unit=''){return `<div class="metric"><span>${label}</span><b>${value}<small> ${unit}</small></b></div>`;}
function afCurrent(){const count=Math.max(1,Math.ceil(progress*data.cells.length)),idx=data.prefixBest[count-1],vi=idx%data.vs.length,hi=Math.floor(idx/data.vs.length),v=data.vs[vi],h=data.hs[hi];return{idx,v,h,gamma:data.cells[idx],residual:data.obs.phase.map((p,i)=>p-P.model(data.obs.t[i],data.obs.B[i],v,h)),count};}
function renderMetrics(){const s=states[stage],m=U().metricLabels;let html='';if(stage===0)html=metric(m[0],'28','mm')+metric(m[1],(s.velocity*3).toFixed(0),'mm');if(stage===1)html=metric(m[2],data.kept.length,'/ 180')+metric(m[3],(100*data.kept.length/180).toFixed(1),'%');if(stage===2){const b=afCurrent();html=metric(m[4],b.v.toFixed(0),'mm/yr')+metric(m[5],b.h.toFixed(0),'m')+metric(m[6],b.gamma.toFixed(3))+metric(m[7],(b.v+8).toFixed(1),'mm/yr');}if(stage===3)html=metric(m[8],data.rmse.toFixed(2),'mm/yr')+metric(s.reject?m[10]:m[9],s.reject?m[11]:Math.abs(data.closure).toFixed(1),s.reject?'':'mm/yr');if(stage===4)html=metric(m[12],data.before.toFixed(3),'rad')+metric(m[13],P.rmse(data.raw.map((v,i)=>v-progress*data.prediction[i]),data.truth).toFixed(3),'rad');if(stage===5)html=metric(m[14],data.x[1].toFixed(2),'mm/yr')+metric(m[15],data.rms.toFixed(2),'mm');if($('metrics').innerHTML!==html)$('metrics').innerHTML=html;}
function recompute(){const s=states[stage];if(stage===0){data={t:Array.from({length:90},(_,i)=>i/89*3)};data.continuous=data.t.map(t=>P.model(t,0,s.velocity,0));data.wrapped=data.continuous.map(P.wrap);}if(stage===1){data={points:P.candidates(sampleSeeds[stage])};data.kept=data.points.filter(p=>p.da<=s.threshold);const order=[...data.points].sort((a,b)=>a.da-b.da);data.stable=order[0];data.unstable=order.at(-1);}if(stage===2){const obs=P.observations({noise:s.noise,seed:sampleSeeds[stage]});data={obs,...P.searchAF(obs)};let best=0;data.prefixBest=data.cells.map((v,i)=>{if(v>data.cells[best])best=i;return best;});}if(stage===3)data=P.network(s.error,s.reject);if(stage===4)data=P.atmosphere(s.length,sampleSeeds[stage]);if(stage===5)data=P.timeSeries({...s,seed:sampleSeeds[stage]});renderMetrics();}
function renderDerivation(){const c=C(),u=U();$('mathPanel').innerHTML=`<div class="math-heading"><div class="eyebrow">${String(stage+1).padStart(2,'0')} / ${u.mathLabel}</div><h2 id="mathTitle">${c.title}</h2><p class="lead">${c.lead}</p></div><div class="math-layout"><div class="proof"><p>${c.description}</p><dl class="notation" aria-label="${u.notation}">${c.notation.map(([symbol,meaning])=>`<div><dt>${symbol}</dt><dd>${meaning}</dd></div>`).join('')}</dl>${c.formulas.map(f=>`<div class="formula">${f}</div>`).join('')}<div class="derivation-prose">${c.steps.map(s=>`<p>${s}</p>`).join('')}</div></div><aside class="method-notes"><div><h3>${c.noteTitle}</h3><p>${c.interpretation}</p></div><div><h3>${u.scope}</h3><p>${c.scope}</p></div><div><h3>${u.related}</h3><div class="related-links">${c.refs.map(n=>{const r=NOTEBOOK_CONTENT.references[n-1];return `<a href="https://doi.org/${r.doi}" target="_blank" rel="noopener noreferrer">[${n}] ${r.authors.split(',')[0]} · ${r.year} ↗<span>${r.doi}</span></a>`;}).join('')}</div></div></aside></div>`;$('previous').textContent='← '+u.previous;$('next').textContent=u.next+' →';$('previous').disabled=stage===0;$('next').disabled=stage===5;$('experimentCounter').textContent=String(stage+1).padStart(2,'0')+' / 06';}
function renderStage(animate=false){const u=U();document.querySelectorAll('[data-tab]').forEach(b=>{const selected=+b.dataset.tab===stage;b.setAttribute('aria-selected',selected);b.tabIndex=selected?0:-1;b.querySelector('span').textContent=u.tabs[+b.dataset.tab];});$('lab-panel').setAttribute('aria-labelledby','tab-'+stage);$('plotTitle').textContent=plotNames[stage];$('stageLabel').textContent=String(stage+1).padStart(2,'0')+' / '+tags[stage];$('stageTitle').textContent=u.tabs[stage];$('stageDescription').textContent=descriptions[lang][stage];$('legend').innerHTML=legends[lang][stage].map(([type,label])=>`<span><i class="${type==='line'?'':type}"></i>${label}</span>`).join('');$('labCanvas').setAttribute('aria-label',u.graph+': '+C().title);$('animationSteps').innerHTML=u.stages[stage].map((s,i)=>`<div data-step="${i}"><span>0${i+1}</span>${s}</div>`).join('');$('experimentNote').textContent='';$('resample').hidden=!stochasticStages.includes(stage);$('resample').title=u.dataPolicy;buildControls();renderDerivation();drawLab();renderMetrics();updateProgress();if(animate&&!reduced){for(const id of ['mathPanel','stageTitle','legend'])$(id).animate([{opacity:0,transform:'translateY(8px)'},{opacity:1,transform:'translateY(0)'}],{duration:360,easing:'cubic-bezier(.22,1,.36,1)'});}}
function setStage(i,focus=false){stage=i;progress=1;pause();recompute();renderStage(true);if(focus)$('tab-'+i).focus({preventScroll:true});}
function setLanguage(value){lang=value;try{localStorage.setItem('psi-language',lang);const url=new URL(location.href);url.searchParams.set('lang',lang);history.replaceState(null,'',url);}catch{}const u=U();document.documentElement.lang=lang==='zh'?'zh-CN':'en';document.title=u.title;document.querySelector('meta[name="description"]').content=u.heroText;document.querySelectorAll('[data-i18n]').forEach(el=>el.innerHTML=u[el.dataset.i18n]);$('language').innerHTML=lang==='zh'?'EN <span aria-hidden="true">↗</span>':'中文 <span aria-hidden="true">↗</span>';$('language').setAttribute('aria-label',u.language);$('timeline').setAttribute('aria-label',u.timeline);$('speed').setAttribute('aria-label',u.speed);$('referenceList').innerHTML=NOTEBOOK_CONTENT.references.map((r,i)=>`<li id="ref-${i+1}"><span class="ref-number">${String(i+1).padStart(2,'0')}</span><div><p>${r.authors} (${r.year}). <em>${r.title}.</em> ${r.venue}.</p><a class="doi-link" href="https://doi.org/${r.doi}" target="_blank" rel="noopener noreferrer">${r.doi} ↗</a></div></li>`).join('');renderStage();syncPlayButton();drawHero();}
const canvas=$('labCanvas');
function setupCanvas(c){let box=c.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2);if(c.width!==Math.round(box.width*dpr)||c.height!==Math.round(box.height*dpr)){c.width=Math.round(box.width*dpr);c.height=Math.round(box.height*dpr);}const g=c.getContext('2d');g.setTransform(dpr,0,0,dpr,0,0);g.clearRect(0,0,box.width,box.height);return{g,w:box.width,h:box.height};}
function txt(g,s,x,y,size=10,color='#71736c',align='left'){g.font=`${size}px ${size<12?'Consolas,monospace':'sans-serif'}`;g.fillStyle=color;g.textAlign=align;g.fillText(s,x,y);}
function line(g,x1,y1,x2,y2,color='#222',width=1,dash=[]){g.beginPath();g.strokeStyle=color;g.lineWidth=width;g.setLineDash(dash);g.moveTo(x1,y1);g.lineTo(x2,y2);g.stroke();g.setLineDash([]);}
function circle(g,x,y,r=2,fill='#171817',stroke=null){g.beginPath();g.arc(x,y,r,0,Math.PI*2);if(fill){g.fillStyle=fill;g.fill();}if(stroke){g.strokeStyle=stroke;g.lineWidth=1;g.stroke();}}
function axes(g,{x,y,w,h,xmin=0,xmax=3,ymin=-1,ymax=1,xticks=3,yticks=4,xlabel='',ylabel=''}){const X=v=>x+(v-xmin)/(xmax-xmin)*w,Y=v=>y+h-(v-ymin)/(ymax-ymin)*h;for(let i=0;i<=yticks;i++){const v=ymin+(ymax-ymin)*i/yticks;line(g,x,Y(v),x+w,Y(v),'#e7e8e1');txt(g,Math.abs(v)>10?v.toFixed(0):Number(v.toFixed(1)).toString(),x-8,Y(v)+3,9,'#82857b','right');}for(let i=0;i<=xticks;i++){const v=xmin+(xmax-xmin)*i/xticks;txt(g,Number(v.toFixed(1)),X(v),y+h+17,9,'#82857b','center');}line(g,x,y+h,x+w,y+h,'#b3b6aa');line(g,x,y,x,y+h,'#b3b6aa');txt(g,xlabel,x+w,y+h+33,9,'#777','right');txt(g,ylabel,x,y-10,9);return{X,Y,x,y,w,h};}
function series(g,a,x,y,{color='#222',width=1.4,dash=[],dots=false,limit=1}={}){g.save();g.beginPath();g.rect(a.x-3,a.y-3,a.w+6,a.h+6);g.clip();g.strokeStyle=color;g.fillStyle=color;g.lineWidth=width;g.setLineDash(dash);g.beginPath();const n=Math.min(x.length,Math.max(1,Math.ceil(x.length*limit)));for(let i=0;i<n;i++){if(dots){circle(g,a.X(x[i]),a.Y(y[i]),2,color);}else{if(i===0)g.moveTo(a.X(x[i]),a.Y(y[i]));else g.lineTo(a.X(x[i]),a.Y(y[i]));}}if(!dots)g.stroke();g.restore();}
function split(w){const gap=48,x=43,width=(w-43-14-gap)/2;return{x,width,x2:x+width+gap};}
function drawLab(){const{g,w,h}=setupCanvas(canvas);if(w<10)return;const s=states[stage],p=progress;
if(stage===0){const max=Math.max(4,...data.continuous.map(Math.abs)),a=axes(g,{x:43,y:24,w:w-58,h:112,ymin:-max,ymax:max,yticks:2,xlabel:'t / yr',ylabel:'continuous phase / rad'});series(g,a,data.t,data.continuous,{limit:p});const b=axes(g,{x:43,y:200,w:w-58,h:92,ymin:-Math.PI,ymax:Math.PI,yticks:2,xlabel:'t / yr',ylabel:'wrapped phase / rad'});series(g,b,data.t,data.wrapped,{dots:true,limit:p});txt(g,'−π ≤ φ < π',w-16,188,10,'#222','right');const k=Math.min(data.t.length-1,Math.floor(p*(data.t.length-1))),ti=data.t[k];line(g,a.X(ti),a.y,a.X(ti),a.y+a.h,'#81867a',1,[3,3]);line(g,b.X(ti),b.y,b.X(ti),b.y+b.h,'#81867a',1,[3,3]);circle(g,a.X(ti),a.Y(data.continuous[k]),4,'white','#111');circle(g,b.X(ti),b.Y(data.wrapped[k]),4,'white','#111');txt(g,'t = '+ti.toFixed(2)+' yr   d = '+(s.velocity*ti).toFixed(1)+' mm',43,339,10,'#222');}
if(stage===1){const q=split(w),size=Math.min(q.width,240),xx=q.x,yy=45,hh=220;txt(g,'SPATIAL DISTRIBUTION',xx,25);line(g,xx,yy+hh,xx+q.width,yy+hh,'#ccc');line(g,xx,yy,xx,yy+hh,'#ccc');data.points.slice(0,Math.ceil(p*180)).forEach(pt=>circle(g,xx+pt.x*q.width,yy+pt.y*hh,pt.da<=s.threshold?2.6:1.7,pt.da<=s.threshold?'#171817':'#d8d9d1'));txt(g,'scene / [0,1]',xx,yy+hh+25,8);const a=axes(g,{x:q.x2,y:45,w:q.width,h:220,xmin:0,xmax:27,ymin:0,ymax:3,yticks:3,xlabel:'epoch',ylabel:'amplitude / a.u.'});const t=Array.from({length:28},(_,i)=>i);series(g,a,t,data.unstable.a,{color:'#92968b',dash:[3,3],limit:p});series(g,a,t,data.stable.a,{limit:p});txt(g,'min dispersion '+data.stable.da.toFixed(2),q.x2,310,10,'#171817');txt(g,'max dispersion '+data.unstable.da.toFixed(2),q.x2,328,10,'#777');}
if(stage===2){const heatW=(w-90)*.64,heatH=230,x=43,y=38,cw=heatW/data.vs.length,ch=heatH/data.hs.length,current=afCurrent();g.fillStyle='#f1f2ec';g.fillRect(x,y,heatW,heatH);for(let k=0;k<current.count;k++){const j=Math.floor(k/data.vs.length),i=k%data.vs.length,v=data.cells[k],gray=Math.round(249-224*v);g.fillStyle=`rgb(${gray},${gray},${gray})`;g.fillRect(x+i*cw,y+heatH-(j+1)*ch,cw+.4,ch+.4);}[-20,0,20].forEach(v=>txt(g,v,x+(v+20)/40*heatW,y+heatH+17,9,'#777','center'));[-30,0,30].forEach(v=>txt(g,v,x-8,y+heatH-(v+30)/60*heatH+3,9,'#777','right'));txt(g,'h / m',x,y-12,9);txt(g,'v / mm·yr⁻¹',x+heatW,y+heatH+35,9,'#777','right');const px=x+(current.v+20)/40*heatW,py=y+heatH-(current.h+30)/60*heatH;circle(g,px,py,6,'white','#111');line(g,px-9,py,px+9,py);line(g,px,py-9,px,py+9);if(p<1){const si=(current.count-1)%data.vs.length,sj=Math.floor((current.count-1)/data.vs.length);g.strokeStyle='#111';g.lineWidth=1;g.strokeRect(x+si*cw,y+heatH-(sj+1)*ch,cw,ch);}
const cx=x+heatW+(w-x-heatW)/2,cy=145,r=Math.min(62,(w-x-heatW)/2-15);circle(g,cx,cy,r,null,'#c7c9c0');line(g,cx-r-7,cy,cx+r+7,cy,'#ddd');line(g,cx,cy-r-7,cx,cy+r+7,'#ddd');current.residual.forEach(a=>line(g,cx,cy,cx+r*Math.cos(a),cy-r*Math.sin(a),'#b1b4a9',.7));const ex=P.mean(current.residual.map(Math.cos)),ey=P.mean(current.residual.map(Math.sin));line(g,cx,cy,cx+r*ex,cy-r*ey,'#111',3);circle(g,cx+r*ex,cy-r*ey,3);txt(g,'residual phasors',cx,cy+r+26,9,'#777','center');txt(g,'γ = '+current.gamma.toFixed(3),cx,cy+r+44,10,'#111','center');txt(g,current.count+' / '+data.cells.length,cx,310,9,'#555','center');}
if(stage===3){const x=38,y=30,ww=w-82,hh=238,coords=data.pts.map(([px,py])=>[x+px*ww,y+py*hh]);data.edges.slice(0,Math.ceil(Math.min(1,p/.55)*data.edges.length)).forEach(e=>{const a=coords[e.i],b=coords[e.j];line(g,...a,...b,e.bad?'#555':'#c0c3b8',e.bad?1.8:1,e.bad?[4,4]:[]);if(e.bad&&s.reject){const mx=(a[0]+b[0])/2,my=(a[1]+b[1])/2;line(g,mx-4,my-4,mx+4,my+4,'#111',1.8);line(g,mx-4,my+4,mx+4,my-4,'#111',1.8);}});coords.forEach(([px,py],i)=>{circle(g,px,py,i===0?6:4,i===0?'white':'#171817',i===0?'#111':null);txt(g,String(i),px-10,py-10,9,'#444','right');if(p>.65){g.save();g.globalAlpha=Math.min(1,(p-.65)/.35);txt(g,data.estimate[i].toFixed(1),px+9,py+15,10,'#111');g.restore();}});txt(g,'POINT 0 / FIXED REFERENCE',20,315,9);txt(g,'labels: estimated mm/yr',w-15,333,9,'#777','right');}
if(stage===4){const q=split(w),ww=q.width,hh=232,yy=38,size=data.size,vmin=-2.2,vmax=1.6;[data.raw,data.raw.map((v,i)=>v-p*data.prediction[i])].forEach((field,k)=>{const xx=k===0?q.x:q.x2;for(let j=0;j<size;j++)for(let i=0;i<size;i++){const v=field[j*size+i],c=Math.max(18,Math.min(246,246-(v-vmin)/(vmax-vmin)*228));g.fillStyle=`rgb(${c},${c},${c})`;g.fillRect(xx+i*ww/size,yy+j*hh/size,ww/size+.5,hh/size+.5);}data.pts.forEach(([x,y])=>circle(g,xx+x*ww,yy+y*hh,1.8,'white','#333'));txt(g,w<500?(k===0?'BEFORE':'AFTER / '+Math.round(p*100)+'%'):(k===0?'BEFORE / d + APS + ε':'AFTER / '+Math.round(p*100)+'% CORRECTION'),xx,25,9,'#111');txt(g,w<500?'phase / rad':'same intensity scale / rad',xx,yy+hh+23,8);});const current=P.rmse(data.raw.map((v,i)=>v-p*data.prediction[i]),data.truth);txt(g,'current corrected RMSE = '+current.toFixed(3)+' rad',q.x,327,10,'#333');}
if(stage===5){const all=[...data.y,...data.truth,...data.fit],ymin=Math.floor(Math.min(...all)/5)*5-2,ymax=Math.ceil(Math.max(...all)/5)*5+2,a=axes(g,{x:44,y:22,w:w-60,h:142,ymin,ymax,yticks:3,xlabel:'',ylabel:'LOS displacement / mm'});series(g,a,data.t,data.truth,{color:'#a2a69b',dash:[4,3],limit:p});series(g,a,data.t,data.fit,{limit:p});series(g,a,data.t,data.y,{dots:true,limit:p});const bound=Math.max(2,Math.ceil(Math.max(...data.residual.map(Math.abs)))),b=axes(g,{x:44,y:220,w:w-60,h:72,ymin:-bound,ymax:bound,yticks:2,xlabel:'t / yr',ylabel:'residual / mm'});series(g,b,data.t,data.residual,{color:'#777',width:1,limit:p});series(g,b,data.t,data.residual,{dots:true,limit:p});const ti=data.t[Math.min(data.t.length-1,Math.floor(p*(data.t.length-1)))];line(g,a.X(ti),a.y,a.X(ti),a.y+a.h,'#a3a69c',1,[3,3]);line(g,b.X(ti),b.y,b.X(ti),b.y+b.h,'#a3a69c',1,[3,3]);}
}

function syncPlayButton(){const u=U(),label=playing?u.pause:progress>=1?u.replay:u.resume;$('play').textContent=(playing?'Ⅱ ':progress>=1?'↻ ':'▶ ')+label;$('play').setAttribute('aria-label',label);}
function pause(){playing=false;lastTime=0;syncPlayButton();}
function updateProgress(){const u=U();$('timeline').value=Math.round(progress*1000);$('timeline').style.setProperty('--fill',Math.round(progress*100)+'%');$('timeline').setAttribute('aria-valuetext',Math.round(progress*100)+'%');$('status').textContent=playing?u.running+' '+Math.round(progress*100)+'%':progress>=1?u.ready:u.paused+' '+Math.round(progress*100)+'%';const step=Math.min(2,Math.floor(progress*3));$('animationSteps').querySelectorAll('[data-step]').forEach(el=>{const i=+el.dataset.step;el.classList.toggle('active',i===step);el.classList.toggle('done',i<step||progress>=1);});if(!playing)$('plotSummary').textContent=C().title+'. '+$('metrics').innerText.replaceAll('\n',' ');}
$('play').addEventListener('click',()=>{if(playing)pause();else{if(progress>=1)progress=0;playing=true;lastTime=0;syncPlayButton();}drawLab();renderMetrics();updateProgress();});
$('resample').addEventListener('click',()=>{const old=sampleSeeds[stage],next=P.randomSeed();sampleSeeds[stage]=next===old?(old+1)>>>0:next;progress=1;pause();recompute();drawLab();updateProgress();if(!reduced)document.querySelector('.plot-area').animate([{opacity:.45},{opacity:1}],{duration:240});});
$('reset').addEventListener('click',()=>{states[stage]={...defaultStates[stage]};setStage(stage);});
$('timeline').addEventListener('input',e=>{progress=+e.target.value/1000;pause();drawLab();renderMetrics();updateProgress();});$('speed').addEventListener('change',e=>{playbackSpeed=+e.target.value;});
$('language').addEventListener('click',()=>setLanguage(lang==='zh'?'en':'zh'));
document.querySelectorAll('[data-tab]').forEach(b=>{b.addEventListener('click',()=>setStage(+b.dataset.tab));b.addEventListener('keydown',e=>{let i=+b.dataset.tab;if(e.key==='ArrowRight')i=(i+1)%6;else if(e.key==='ArrowLeft')i=(i+5)%6;else if(e.key==='Home')i=0;else if(e.key==='End')i=5;else return;e.preventDefault();setStage(i,true);});});
$('previous').addEventListener('click',()=>{if(stage>0){setStage(stage-1,true);$('lab').scrollIntoView({behavior:reduced?'instant':'smooth'});}});$('next').addEventListener('click',()=>{if(stage<5){setStage(stage+1,true);$('lab').scrollIntoView({behavior:reduced?'instant':'smooth'});}});
$('download').addEventListener('click',()=>{const scopeText=document.createElement('span');scopeText.innerHTML=C().scope;const algorithms=['phase-wrapping','amplitude-dispersion','ambiguity-function-grid','relative-network-least-squares','zero-mean-simple-kriging','linear-seasonal-least-squares'],payload={project:'PSI-SimLab',schemaVersion:3,language:lang,experiment:stage+1,algorithm:algorithms[stage],synthetic:true,seed:stochasticStages.includes(stage)?sampleSeeds[stage]:null,parameters:states[stage],constants:{wavelength_m:.056,range_m:800000,incidence_deg:35},scope:scopeText.textContent,playbackProgress:progress,results:data},blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=`psi-experiment-${String(stage+1).padStart(2,'0')}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
function drawHero(time=0){const c=$('heroCanvas'),{g,w,h}=setupCanvas(c),cx=w*.52,cy=h*.52;g.fillStyle='#eeeeea';g.fillRect(0,0,w,h);const r=P.rng(heroSeed);for(let j=0;j<24;j++){const base=13+j*9;g.beginPath();for(let k=0;k<=220;k++){const a=k/220*P.TAU,rad=base*(1+.09*Math.cos(3*a)+.05*Math.sin(5*a+j*.08)),x=cx+rad*Math.cos(a)*1.1+Math.sin(a*2)*j*.5,y=cy+rad*Math.sin(a)*.66; k?g.lineTo(x,y):g.moveTo(x,y);}g.strokeStyle=j%4===0?'#363a31':'#9a9d91';g.lineWidth=j%4===0?.9:.55;g.stroke();}for(let i=0;i<230;i++){const x=30+r()*(w-60),y=62+r()*(h-124);circle(g,x,y,r()>.88?1.7:.65,r()>.8?'#161914':'#9fa394');}line(g,cx-15,cy,cx+15,cy,'#111',.8);line(g,cx,cy-15,cx,cy+15,'#111',.8);txt(g,'REF.',cx+19,cy-8,9,'#444');if(!reduced){const y=65+(time*.026)%(h-130);const gradient=g.createLinearGradient(0,y-28,0,y);gradient.addColorStop(0,'rgba(90,95,80,0)');gradient.addColorStop(1,'rgba(90,95,80,.06)');g.fillStyle=gradient;g.fillRect(20,y-28,w-40,28);line(g,20,y,w-20,y,'#a5a999',.8);line(g,20,y,27,y,'#222',2);line(g,w-27,y,w-20,y,'#222',2);}const barx=24,bary=h-53;line(g,barx,bary,barx+65,bary,'#333',1.3);line(g,barx,bary-3,barx,bary+3,'#333');line(g,barx+65,bary-3,barx+65,bary+3,'#333');txt(g,'NORMALIZED SCENE',barx+75,bary+3,8);}

let lastDraw=0;function frame(time){if(!document.hidden){if(playing&&labVisible){if(!lastTime)lastTime=time;const elapsed=Math.min(80,time-lastTime);progress=Math.min(1,progress+elapsed*playbackSpeed/(stage===2?8500:6000));lastTime=time;drawLab();updateProgress();if(time-lastMetricTime>180||progress>=1){renderMetrics();lastMetricTime=time;}if(progress>=1){pause();updateProgress();}}else lastTime=0;if(heroVisible&&!reduced&&time-lastDraw>50){drawHero(time);lastDraw=time;}}else lastTime=0;requestAnimationFrame(frame);}
const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.target.id==='heroCanvas')heroVisible=e.isIntersecting;else if(e.target.id==='lab')labVisible=e.isIntersecting;}));observer.observe($('heroCanvas'));observer.observe($('lab'));
const revealObserver=new IntersectionObserver(entries=>entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('is-visible');revealObserver.unobserve(e.target);}}),{threshold:.08});document.querySelectorAll('.reveal').forEach(el=>revealObserver.observe(el));
new ResizeObserver(()=>{if(data)drawLab();drawHero();}).observe(document.querySelector('.plot-area'));new ResizeObserver(()=>drawHero()).observe($('heroCanvas').parentElement);
document.addEventListener('visibilitychange',()=>{lastTime=0;});recompute();setLanguage(lang);drawHero();requestAnimationFrame(frame);
